import { randomSeed } from '@/engine/rng';
import type { GameModule, SeatIndex } from '@/engine/types';
import { useGameStore } from '@/store/gameStore';
import { useNetworkStore } from '@/store/networkStore';

// One launcher for every game's setup screen: start a solo / hot-seat game
// on this device, or open an online lobby (the room code is generated by the
// network layer). Keeps the 11 setup screens from each re-implementing it.

export interface LaunchArgs {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  module: GameModule<any, any, any>;
  /** The game's options object (its `players` list is overwritten). */
  options: object;
  /** One name per seat, in seat order. */
  playerNames: string[];
  /** Seats driven by the AI. */
  aiSeats?: SeatIndex[];
  /** Open an online lobby instead of starting locally. */
  online: boolean;
}

export function launchGame({ module, options, playerNames, aiSeats = [], online }: LaunchArgs): void {
  const names = playerNames.map((n, i) => n.trim() || `Player ${i + 1}`);
  const players = names.map((name, i) => ({ name, isAI: aiSeats.includes(i) }));
  const gameOptions = { ...(options as Record<string, unknown>), players };
  if (online) {
    void useNetworkStore.getState().hostRoom(module.id, {
      seatCount: names.length,
      names,
      options: gameOptions,
      aiSeats,
    });
    return;
  }
  const config = {
    gameId: module.id,
    seats: names.map((name, i) => ({ index: i, uuid: null, name, isAI: aiSeats.includes(i) })),
    seed: randomSeed(),
    gameOptions,
  };
  const initialState = module.createInitialState(config);
  const firstHuman = names.findIndex((_, i) => !aiSeats.includes(i));
  useGameStore
    .getState()
    .startLocalGame(module, initialState, firstHuman >= 0 ? firstHuman : null, { aiSeats });
}
